@WebMvcTest(OrderController.class)
class OrderControllerTest {

    @Autowired
    private MockMvc mockMvc;

    @MockBean
    private OrderService orderService; // Service not loaded, must mock it

    @Test
    void shouldReturnOrderById() throws Exception {
        var order = new Order(1L, "Laptop", 999.99);
        when(orderService.findById(1L)).thenReturn(Optional.of(order));

        mockMvc.perform(get("/api/orders/1")) // Simulate GET request
               .andExpect(status().isOk())
               .andExpect(jsonPath("$.id").value(1))
               .andExpect(jsonPath("$.item").value("Laptop"));
    }
}

@WebMvcTest(ProductController.class)
class ProductControllerTest {

    @Autowired
    private MockMvc mockMvc;

    @MockBean
    private ProductService productService;

    @Test
    void shouldReturnProductListWithOkStatus() throws Exception {
        // Arrange: stub the service to return test data
        var products = List.of(
            new Product(1L, "Laptop", 1200.00),
            new Product(2L, "Mouse", 25.00)
        );
        when(productService.getAllProducts()).thenReturn(products);

        // Act & Assert: perform GET and verify response
        mockMvc.perform(get("/api/products"))
               .andExpect(status().isOk()) // Verify HTTP 200
               .andExpect(jsonPath("$[0].name").value("Laptop"))
               .andExpect(jsonPath("$[1].price").value(25.00));
    }
}

@WebMvcTest(UserController.class)
class UserControllerTest {

    @Autowired
    private MockMvc mockMvc;

    @MockBean
    private UserService userService; // Service not loaded, must mock

    @MockBean
    private EmailNotificationService emailService; // Another dependency

    @Test
    void shouldCreateUserSuccessfully() throws Exception {
        var newUser = new User(null, "alice@example.com");
        var savedUser = new User(10L, "alice@example.com");

        when(userService.createUser(any(User.class))).thenReturn(savedUser);

        mockMvc.perform(post("/api/users")
               .contentType(MediaType.APPLICATION_JSON)
               .content("{\"email\":\"alice@example.com\"}"))
               .andExpect(status().isCreated())
               .andExpect(jsonPath("$.id").value(10));
    }
}

@WebMvcTest(OrderController.class)
class OrderControllerTest {

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private ObjectMapper objectMapper; // Injected by Spring

    @MockBean
    private OrderService orderService;

    @Test
    void shouldCreateOrderAndReturn201() throws Exception {
        var newOrder = new Order(null, "Gaming PC", 1500.00);
        var savedOrder = new Order(42L, "Gaming PC", 1500.00);

        when(orderService.createOrder(any(Order.class))).thenReturn(savedOrder);

        mockMvc.perform(post("/api/orders")
               .contentType(MediaType.APPLICATION_JSON) // Required for JSON body
               .content(objectMapper.writeValueAsString(newOrder))) // Serialize to JSON
               .andExpect(status().isCreated())
               .andExpect(jsonPath("$.id").value(42))
               .andExpect(jsonPath("$.item").value("Gaming PC"));
    }
}

@WebMvcTest(OrderController.class)
class OrderControllerTest {
    @Autowired
    private MockMvc mockMvc;

    @MockBean
    private OrderService orderService;

    @Test
    void shouldReturn404WhenOrderNotFound() throws Exception {
        var orderId = 999L;
        // Stub service to throw exception
        when(orderService.findById(orderId))
            .thenThrow(new ResourceNotFoundException("Order not found"));

        mockMvc.perform(get("/api/orders/{id}", orderId))
            .andExpect(status().isNotFound())
            .andExpect(jsonPath("$.message").value("Order not found"));
    }
}

@ControllerAdvice
class GlobalExceptionHandler {
    @ExceptionHandler(ResourceNotFoundException.class)
    @ResponseStatus(HttpStatus.NOT_FOUND)  // Maps to 404
    public ErrorResponse handleNotFound(ResourceNotFoundException ex) {
        return new ErrorResponse(ex.getMessage());
    }
}

record ErrorResponse(String message) {}

